const $=id=>document.getElementById(id);
function mileageCopyControl(value){
 const group=document.createElement('span');group.className='mileage-copy';
 const button=document.createElement('button');button.type='button';button.className='copy-mileage';button.textContent='點此複製';button.setAttribute('aria-label','複製公里數 '+value);
 const feedback=document.createElement('span');feedback.className='copy-feedback';feedback.setAttribute('role','status');
 button.onclick=async()=>{
  button.disabled=true;feedback.textContent='';
  try{
   try{await navigator.clipboard.writeText(value);}catch{
    const input=document.createElement('textarea');input.value=value;input.setAttribute('readonly','');input.style.cssText='position:fixed;top:0;left:0;opacity:0;pointer-events:none';document.body.append(input);
    try{input.focus();input.select();if(!document.execCommand('copy'))throw new Error('copy failed');}finally{input.remove();button.focus();}
   }
   feedback.textContent='已複製 '+value;button.textContent='再次複製';
  }catch{feedback.textContent='複製失敗，請選取公里數手動複製。';}
  finally{button.disabled=false;}
 };
 group.append(button,feedback);return group;
}
