function renderTrain(){const panel=$('hsrTablePanel');panel.replaceChildren();const title=document.createElement('h2'),note=document.createElement('p'),link=document.createElement('a');title.textContent='搭乘火車';note.textContent='請至台鐵官方網站查詢票價，依實際票價辦理報支。';link.className='gmaps-btn';link.textContent='台鐵票價查詢（另開分頁）';link.href='https://www.railway.gov.tw/tra-tip-web/tip/tip001/tip114/query';link.target='_blank';link.rel='noopener noreferrer';panel.append(title,note,link);}
