function multiMileageBreakdown(segments,totalKm){
 const process=document.createElement('div');process.className='mileage-breakdown';
 const title=document.createElement('div');title.textContent='里程計算過程';process.append(title);
 for(const segment of segments){const row=document.createElement('div');row.textContent=segment.from+' → '+segment.to+'：'+segment.km.toFixed(1)+' 公里';process.append(row);}
 const sum=document.createElement('div');sum.className='mileage-sum';sum.textContent=segments.map(segment=>segment.km.toFixed(1)).join(' + ')+' = '+totalKm.toFixed(1)+' 公里';process.append(sum);return process;
}
async function multiMileage(origin,stops,mode){
 const names=[origin,...stops],memo=new Map(),notes=[],segments=[];let outKm=0,returnKm=0,outside=false;
 const point=async name=>{if(!memo.has(name))memo.set(name,await geocode(name));return memo.get(name);};
 const segment=async (a,b,stored)=>{let km,source;if(stored){km=roundKm(stored.outKm);source='單程資料';}else if(placeAddress(normalizePlace(a))===placeAddress(normalizePlace(b))){km=0;source='同地點';}else{const start=await point(a),end=await point(b),road=await route([start,end],mode==='scooter');outside=outside||start.outside||end.outside;km=roundKm(road.distance/1000);source='道路查詢';}segments.push({from:a,to:b,km,source});notes.push(a+' → '+b+'：'+km.toFixed(1)+' 公里（'+source+'）');return km;};
 for(let i=1;i<names.length;i++)outKm+=await segment(names[i-1],names[i],i===1&&hasFixedOrigin(names[i])?fixedMileage(names[i]):null);
 if($('roundTrip').checked){returnKm=await segment(names.at(-1),origin,hasFixedOrigin(names.at(-1))?fixedMileage(names.at(-1)):null);}
 outside=outside||stops.some(name=>['彰化師範大學','台中教育大學','國教署','高師大','中山醫學大學'].includes(normalizePlace(name)));
 return {mixed:true,approximate:[...memo.values()].some(p=>p.approximate),outKm,returnKm,outside,segments,routeNote:notes.join('；')};
}
async function calculate(){if(busy)return;const startRevision=revision,origin=$('origin').value.trim(),stops=addresses(),mode=$('mode').value;if(!origin||!stops.length){status('請填寫起點及至少一個目的地。',true);return;}stops.forEach(rememberDestination);busy=true;$('go').disabled=true;cache=null;$('result').hidden=true;clearMap();try{if(fixed()){const mileage=fixedMileage(stops[0]);cache={fixed:true,inputKey:fixedResultKey(),...mileage,outside:['彰化師範大學','台中教育大學','國教署','高師大','中山醫學大學'].includes(normalizePlace(stops[0]))};status('');$('mapNote').textContent='';$('mapNote').hidden=!!cache.source;}else if(stops.length>1){status('正在依序計算各站單程里程…');const data=await multiMileage(origin,stops,mode);if(startRevision!==revision)return;cache=data;$('mapNote').hidden=true;status(cache.approximate?'計算完成；地圖結果為模糊比對，請用 Google Maps 確認目的地。':'計算完成',false,cache.approximate?'確認目的地':'');}else{status('正在查詢地點與道路里程…');const points=[await geocode(origin)];for(const address of stops)points.push(await geocode(address));const out=await route(points,mode==='scooter');let back=null;if($('roundTrip').checked||points.length>2)back=await route([points.at(-1),points[0]],mode==='scooter');if(startRevision!==revision)return;cache={points,approximate:points.some(p=>p.approximate),routeNote:out.selectionNote+(back?'；回程：'+back.selectionNote:''),outKm:roundKm(out.distance/1000),returnKm:roundKm(back?back.distance/1000:out.distance/1000),outside:points.slice(1).some(p=>p.outside)};if(map){for(const [r,color]of [[out,'#FF9F1C'],[back,'#3A86C8']])if(r)layers.push(L.polyline(r.geometry.coordinates.map(c=>[c[1],c[0]]),{color,weight:5}).addTo(map));points.forEach((p,i)=>layers.push(L.circleMarker([p.lat,p.lon],{radius:7}).bindTooltip(i===0?'起點':'目的地 '+i).addTo(map)));map.fitBounds(L.featureGroup(layers).getBounds(),{padding:[30,30]});$('mapNote').hidden=true;}status(cache.approximate?'計算完成；地圖結果為模糊比對，請用 Google Maps 確認目的地。':'計算完成',false,cache.approximate?'確認目的地':'');}if(startRevision===revision)render();}catch(e){if(startRevision===revision)status(e.message,true,e.locationQuery);}finally{busy=false;$('go').disabled=false;}}
$('origin').oninput=()=>{if(!isSchool())$('preset').value='';invalidate();};$('origin').onchange=refreshFixed;$('preset').onchange=()=>{if($('preset').value){$('stops').replaceChildren();addStop($('preset').value);}refreshFixed();};$('add').onclick=()=>{$('preset').value='';addStop();invalidate();};$('mode').onchange=()=>{invalidate();modeVisibility();if(fixed()&&!['hsr','train'].includes($('mode').value))calculate();};$('go').onclick=calculate;
for(const id of ['roundTrip','day','tier','miscEnabled'])$(id).onchange=()=>{$('day').disabled=$('tier').disabled=!$('miscEnabled').checked;if(id==='roundTrip'&&cache&&!cache.fixed){invalidate();status('單程／來回已變更，請重新計算道路路線。');}else render();};
